--   치환하고 나니 같아졌다
--   이름만 다르다


-- 이름을 값으로 넘겨 본다

public class CommonProxy {
    private final Object target;
    private final LogTrace trace;

    public void call(String methodName, Object arg) throws Exception {
        TraceStatus status = null;
        try {
            status = trace.begin(target.getClass().getSimpleName() + "." + methodName + "()");
            Method m = target.getClass().getMethod(methodName, String.class);
            m.invoke(target, arg);                    // 이름으로 부른다
            trace.end(status);
        } catch (Exception e) {
            trace.exception(status, e);
            throw e;
        }
    }
}

