// 후
private Object callWithLog(Method method, Object target, Object... args)
        throws Exception {
    TraceStatus status = null;
    try {
        status = trace.begin(method.getDeclaringClass().getSimpleName()
                             + "." + method.getName() + "()");
        Object result = method.invoke(target, args);
        trace.end(status);
        return result;
    } catch (Exception e) {
        trace.exception(status, e);
        throw e;
    }
}

